import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Combat status and open questions","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/combat/status-and-open-questions.md","filePath":"en/game-design/combat/status-and-open-questions.md"}'),r={name:"en/game-design/combat/status-and-open-questions.md"};function o(d,e,s,l,c,m){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="combat-status-and-open-questions" tabindex="-1">Combat status and open questions <a class="header-anchor" href="#combat-status-and-open-questions" aria-label="Permalink to &quot;Combat status and open questions&quot;">​</a></h1><p><strong>Design status: mixed, itemized below. Reviewed: 2026-10-08. This is a navigation and reconciliation summary; linked pages own the rules.</strong></p><p><a href="/Syrolands-Public/en/guide/combat/overview.html">Player overview</a> · <a href="/Syrolands-Public/en/game-design/combat/overview.html">Combat foundations</a></p><h2 id="design-implementation-and-evidence" tabindex="-1">Design, implementation and evidence <a class="header-anchor" href="#design-implementation-and-evidence" aria-label="Permalink to &quot;Design, implementation and evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mechanic</th><th>Design state</th><th>Implementation / evidence boundary</th></tr></thead><tbody><tr><td>Automatic default and server-resolved combat</td><td>Accepted</td><td>Existing baseline; no new manual input in Batch 03</td></tr><tr><td>Seven human regions, integrity thresholds and session lifecycle</td><td>Accepted Experimental policy</td><td>Stage 2A local state; exact rules remain in <a href="/Syrolands-Public/en/game-design/combat/body-regions.html">body regions</a></td></tr><tr><td>Global Hits distinct from local trauma; residual ×2 with lifecycle/HP gate</td><td>Accepted Experimental policy</td><td>Stage 2A natural melee integration; <a href="/Syrolands-Public/en/game-design/combat/damage.html">damage</a> owns unchanged arithmetic</td></tr><tr><td>Coverage/contact and shared-item armor wear</td><td>Accepted Experimental adapter</td><td>Legacy adapter; not expanded material physics</td></tr><tr><td>Qualitative Anatomy disclosure</td><td>Accepted scoped behavior</td><td>Stage 2A; <a href="/Syrolands-Public/en/game-design/skills-and-knowledge.html">disclosure limits</a> remain unchanged</td></tr><tr><td>Aimed region</td><td>Accepted direction and Experimental resolver policy</td><td>Pure resolver exists; player intent and hit integration deferred, not live aiming</td></tr><tr><td>Disabled shield-supporting arm</td><td>Accepted consequence; Experimental Left Arm convention</td><td>Transition primitives exist; shield stow/equip restriction deferred</td></tr><tr><td>Other disability penalties, bleeding, specialized wounds and Healing</td><td>Proposed / Unresolved</td><td>Not established by the local-state primitive</td></tr><tr><td>Weapon families, material transmission, condition effects and traits</td><td>Proposed / Unresolved</td><td>No new implementation in this batch</td></tr><tr><td>Expanded stamina, recovery and bounded stat influence</td><td>Proposed / Unresolved</td><td>Inherited behavior remains; the redesign is not implemented</td></tr><tr><td>Manual attack input</td><td>Proposed; compatibility Unresolved</td><td><a href="/Syrolands-Public/en/game-design/combat/stamina-and-reactive-combat.html#automatic-baseline-and-manual-input-conflict">Conflict with mandatory input</a>; no chosen binding or contract</td></tr><tr><td>Concentration pressure</td><td>Proposed / Unresolved</td><td><a href="/Syrolands-Public/en/game-design/magic.html#concentration-under-pressure">Magic</a> owns the design</td></tr></tbody></table><p>Automated checks and a first client observation are recorded, but current availability is not verified here. Initial observation does not establish balance, full lifecycle behavior, armor interactions or complete Anatomy validation. No new game session was run for this documentation.</p><h2 id="unresolved-decisions" tabindex="-1">Unresolved decisions <a class="header-anchor" href="#unresolved-decisions" aria-label="Permalink to &quot;Unresolved decisions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Questions retained for later design and evaluation</th></tr></thead><tbody><tr><td>Location and intent</td><td>Final natural limb distribution; aimed accuracy, cost and contributing factors. Existing experimental weights and 50% aimed policy remain intact, not final balance.</td></tr><tr><td>Stamina and tempo</td><td>Attack costs, fatigue representation, regeneration, recovery timing, missed/canceled attempts and repeated-action pressure.</td></tr><tr><td>Stats and martial skills</td><td>Bounded DEX and STR contributions; Tactics role beyond damage scaling; avoid a universal mandatory weapon/Tactics/Anatomy/Healing bundle.</td></tr><tr><td>Injuries and medicine</td><td>Bleeding thresholds, wound types, Healing/stabilization, local recovery and persistence beyond the session fixture.</td></tr><tr><td>Armor and equipment</td><td>Penetration/deflection, blunt transmission, layering, condition transitions and exact special-trait interactions with limbs/armor.</td></tr><tr><td>Combat balance</td><td>PvP time-to-kill targets and PvM scaling; shared rules without imposing human anatomy on every creature.</td></tr><tr><td>Creatures and range</td><td>NPC eligibility, large-creature profiles, nonhuman anatomy and ranged targeted shots.</td></tr><tr><td>Input and animation</td><td>Whether manual attacks are optional or replace auto; weapon timing, animation capabilities and client limitations.</td></tr><tr><td>Network and access</td><td>Reactive-input networking, latency fairness, remapping/accessibility, anti-macro/automation implications and unsupported-client behavior.</td></tr></tbody></table><h2 id="canonical-ownership-and-reconciliation" tabindex="-1">Canonical ownership and reconciliation <a class="header-anchor" href="#canonical-ownership-and-reconciliation" aria-label="Permalink to &quot;Canonical ownership and reconciliation&quot;">​</a></h2><p>The <a href="/Syrolands-Public/en/game-design/combat/body-regions.html">body model</a>, <a href="/Syrolands-Public/en/game-design/combat/damage.html">trauma policy</a>, <a href="/Syrolands-Public/en/game-design/combat/targeting.html">targeting resolver</a> and <a href="/Syrolands-Public/en/game-design/combat/disability.html">shield rule</a> are preserved. Batch 03 expands the proposal around them; it does not silently supersede accepted experiments. <a href="/Syrolands-Public/en/game-design/combat/weapons-and-damage.html">Weapon identity</a>, <a href="/Syrolands-Public/en/game-design/combat/armor-and-mitigation.html">armor interaction</a> and <a href="/Syrolands-Public/en/game-design/combat/stamina-and-reactive-combat.html">stamina/input</a> centralize the new directions.</p><p><a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html#weapon-quality-dimensions">Quality definitions</a>, <a href="/Syrolands-Public/en/game-design/characters/stats.html">stats</a>, <a href="/Syrolands-Public/en/game-design/skills-and-knowledge.html">skills and knowledge</a>, <a href="/Syrolands-Public/en/game-design/professions/profession-system.html">profession maintenance</a>, <a href="/Syrolands-Public/en/game-design/equipment-and-loot.html">loss economics</a> and <a href="/Syrolands-Public/en/game-design/magic.html">Magic</a> retain their own authority. Proposed high-end equipment cannot change the prototype trauma formula or accepted replaceability by implication.</p><h2 id="related-design" tabindex="-1">Related design <a class="header-anchor" href="#related-design" aria-label="Permalink to &quot;Related design&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/combat/status-and-open-questions.html">Status and unresolved decisions</a></p><h2 id="batch-05-normalization-—-proposed" tabindex="-1">Batch 05 normalization — Proposed <a class="header-anchor" href="#batch-05-normalization-—-proposed" aria-label="Permalink to &quot;Batch 05 normalization — Proposed&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/combat/legacy-and-modern.html">Legacy/Modern</a> clarifies the previous optional-versus-replacement ambiguity: Modern is preferred for experiments, Legacy retained as a supported alternative. No automatic foundation is silently reclassified. Actions, queue/cancel behavior, immediate defense, Flow, reach, ranged release and shared Familiarity remain Proposed.</p><p><a href="/Syrolands-Public/en/game-design/combat/variable-registry.html">The 40-concept registry</a> centralizes definitions, owners and tuning needs. Open questions include valid-input timing, action overlap/recovery, spatial/visual feasibility, mode switching, latency/accessibility, stored ranged-result expiry, resource charging, active-day maintenance/anti-macro, training access, repertoire changes, Flow windows and explicit numerical trade-offs. No new values replace existing experimental policies.</p><h2 id="batch-06-—-experimental-numbers-no-gameplay-change" tabindex="-1">Batch 06 — Experimental numbers, no gameplay change <a class="header-anchor" href="#batch-06-—-experimental-numbers-no-gameplay-change" aria-label="Permalink to &quot;Batch 06 — Experimental numbers, no gameplay change&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/combat/numeric-prototype.html">Numeric prototype</a> and <a href="/Syrolands-Public/en/game-design/combat/variable-registry.html#batch-06-implementation-triage">40-variable triage</a> define a bounded future test. Phase/resource/cadence numbers are Experimental; Modern remains Proposed. Accepted health, trauma and authority policies remain unchanged. Damage integration, visible reach, latency, accessibility and maintenance abuse controls still block implementation claims.</p>',18)])])}const p=a(r,[["render",o]]);export{u as __pageData,p as default};
